package vn.xuannhashop.business.identity.application;
import java.util.*;import java.time.LocalDate;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import vn.xuannhashop.business.shared.*;import vn.xuannhashop.business.shared.security.ActorContext;import vn.xuannhashop.business.shared.audit.ActivityService;
@Service public class CustomerVerificationService implements CustomerVerificationApplication {
    private final CustomerVerificationRepository r;private final ActorContext actor;private final Commands commands;private final ActivityService audit;
    public CustomerVerificationService(CustomerVerificationRepository r,ActorContext actor,Commands commands,ActivityService audit){this.r=r;this.actor=actor;this.commands=commands;this.audit=audit;}
    public Map<String,Object> publicPolicy(){var p=r.policy();return p==null?Map.of("version",0,"required",false,"title","Chưa công bố chính sách xác minh","criteria",""):Map.of("version",p.get("version"),"required",p.get("required"),"title",p.get("title"),"criteria",p.get("criteria"));}
    public Map<String,Object> overview(){actor.require("OWNER","MANAGER","INVENTORY");return r.overview();}
    @Transactional public UUID publish(Policy c,String key){actor.require("OWNER");if(c==null||c.expectedVersion()==null||c.expectedVersion()<0)throw DomainException.bad("Cần phiên bản chính sách.");Checks.text(c.title(),180,"Tên chính sách");Checks.text(c.criteria(),6000,"Tiêu chí xác minh");Checks.text(c.reason(),1000,"Căn cứ công bố");return commands.once(key,"ELIGIBILITY_POLICY:"+c,()->{r.lockPolicy();var p=r.policy();long version=p==null?0:((Number)p.get("version")).longValue();if(c.expectedVersion()!=version)throw DomainException.conflict("Chính sách đã thay đổi, tải lại.");r.publish(c,actor.username());UUID id=UUID.randomUUID();audit.record("ELIGIBILITY_POLICY_PUBLISHED",id,"v"+(version+1)+"; required="+c.required());return id;});}
    @Transactional public UUID verify(Verification c,String key){actor.require("OWNER","MANAGER");if(c==null||c.customerId()==null||c.policyVersion()==null||c.validUntil()==null||c.validUntil().isBefore(LocalDate.now())||c.validUntil().isAfter(LocalDate.now().plusYears(1)))throw DomainException.bad("Cần khách, phiên bản và thời hạn xác minh trong một năm.");Checks.text(c.method(),180,"Cách đối chiếu");Checks.text(c.referenceHint(),80,"Mã tham chiếu đã che");Checks.text(c.note(),1000,"Kết luận đối chiếu tiêu chí");return commands.once(key,"CUSTOMER_VERIFY:"+c,()->{r.lockPolicy();var p=r.policy();if(p==null||((Number)p.get("version")).longValue()!=c.policyVersion())throw DomainException.conflict("Công bố hoặc tải lại chính sách trước khi xác minh.");var customer=r.customer(c.customerId());if(customer==null)throw DomainException.missing();UUID id=UUID.randomUUID();r.verify(id,c,((Number)customer.get("version")).longValue(),actor.username());audit.record("CUSTOMER_VERIFIED",c.customerId(),"verification="+id+"; passed="+c.passed());return id;});}
    @Transactional public void requireEligible(UUID id){r.lockPolicy();var p=r.policy();if(p==null||!Boolean.TRUE.equals(p.get("required")))return;var c=r.customer(id);if(c==null)throw DomainException.missing();var v=r.latest(id);if(v==null||!Boolean.TRUE.equals(v.get("passed"))||!v.get("policy_version").equals(p.get("version"))||!v.get("customer_version").equals(c.get("version"))||((LocalDate)v.get("valid_until")).isBefore(LocalDate.now()))throw DomainException.conflict("Khách cần được xác minh theo chính sách hiện hành trước khi xác nhận/giao thiết bị.");}
}
